%拟合 
n1=[1:10:832,2:10:832,8:10:832,4:10:832,5:10:832,10:10:832,7:10:832]; 
n2=[3:10:832,6:10:832,9:10:832]; 
%% 平均距离 
[mean_ord]=dis_around(address_order,address_user); 
plot(mean_ord(n1),price(n1),'.') 
hold on 
plot(mean_ord(n2),price(n2),'.r') 
hold on 
p=fittype('q1*x^0.5+q2*x + q3','independent','x'); 
[fitobject,gof,output]=fit(mean_ord(n1)',price(n1),p); 
t=0:1:25000; 
z=fitobject.q1*t.^0.5+fitobject.q2*t + fitobject.q3; 
plot(t,z,'r') 
hold on 
price_dis_or=fitobject.q1*mean_ord(n1).^0.5+fitobject.q2*mean_ord(n1) 
+ 
fitobject.q3; 
SSE_dis_or=sum((price(n1)-price_dis_or').^2);%原平方残差 
ave_SSE_dis_or=SSE_dis_or/length(n1) 
price_dis=fitobject.q1*mean_ord(n2).^0.5+fitobject.q2*mean_ord(n2) + fitobject.q3; 
SSE_dis=sum((price(n2)-price_dis').^2);%平方残差 
ave_SSE_dis=SSE_dis/length(n2) 
precent_SSE_dis=(ave_SSE_dis-ave_SSE_dis_or)/ave_SSE_dis_or 
%% 限额 
[num,limitednum]=amount(user_limit,D,1000); 
plot(limitednum(n1),price(n1),'.') 
hold on 
plot(limitednum(n2),price(n2),'.r') 
hold on

